const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/document_markup_downloadable_pdfs/find_or_create',
  qs: {version_datetime: 'SOME_STRING_VALUE'},
  headers: {'content-type': 'application/json'},
  body: {project_id: 0, item_id: 0, item_type: 'SubmittalLogApprover', attachment_id: 0},
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/document_markup_downloadable_pdfs/find_or_create?version_datetime=SOME_STRING_VALUE"),
    Content = new StringContent("{\"project_id\":0,\"item_id\":0,\"item_type\":\"SubmittalLogApprover\",\"attachment_id\":0}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
